--TABLA VENDEDORES 
CREATE TABLE Vendedores (
    id_vendedor VARCHAR(10) PRIMARY KEY,
    nombre VARCHAR(100) NOT NULL,
    telefono VARCHAR(20),
    canal VARCHAR(30) NOT NULL,

    CHECK (canal IN ('Territorio', 'Mayorista'))
)
GO

GO

SELECT * FROM Vendedores

-- TABLA UNIDADES
CREATE TABLE Unidades (
    id_unidad VARCHAR(10) PRIMARY KEY,
    canal VARCHAR(30) NOT NULL,
    tipo_camion VARCHAR(30) NOT NULL,
    capacidad_toneladas DECIMAL(5,2) NOT NULL,
    carga_kg INT NOT NULL,
    restriccion_municipal VARCHAR(2) NOT NULL,

    CHECK (canal IN ('Territorio', 'Mayorista')),
    CHECK (restriccion_municipal IN ('Si', 'No'))
)
GO


