-- TABLA MERCADOS
CREATE TABLE Mercados (
    id_mercado VARCHAR(10) PRIMARY KEY,
    nombre_mercado VARCHAR(150) NOT NULL,
    tipo_mercado VARCHAR(20) NOT NULL,
    ubicacion VARCHAR(150),
    id_distrito VARCHAR(10) NOT NULL,

    FOREIGN KEY (id_distrito) REFERENCES Distritos(id_distrito),

    CHECK (tipo_mercado IN ('Mayorista', 'Minorista'))
)
GO

