--TABLA CLIENTES 
CREATE TABLE Clientes (
    id_cliente VARCHAR(10) PRIMARY KEY,
    nombre_cliente VARCHAR(150) NOT NULL,
    tipo_cliente VARCHAR(30) NOT NULL,
    direccion VARCHAR(200),
    punto_referencia VARCHAR(150),
    id_zona VARCHAR(10) NOT NULL,
    id_vendedor VARCHAR(10),

    FOREIGN KEY (id_zona) REFERENCES Zonas(id_zona),
    FOREIGN KEY (id_vendedor) REFERENCES Vendedores(id_vendedor),

    CHECK (tipo_cliente IN (
        'Bodega',
        'Minimarket',
        'Panaderia',
        'Tottus',
        'Plaza Vea',
        'Precio Uno',
        'Puesto de mercado'
    ))
)
GO

go
SELECT * FROM Clientes

CREATE TABLE Recorridos (
    id_recorrido VARCHAR(10) PRIMARY KEY,
    fecha DATE NOT NULL,
    turno VARCHAR(10) NOT NULL,
    id_zona VARCHAR(10) NOT NULL,
    id_unidad VARCHAR(10) NOT NULL,
    id_vendedor VARCHAR(10) NOT NULL,
    clientes_visitados INT NOT NULL,
    ventas DECIMAL(10,2) NOT NULL,
    monto_regreso DECIMAL(10,2) NOT NULL,
    mapeo VARCHAR(20),

    FOREIGN KEY (id_zona) REFERENCES Zonas(id_zona),
    FOREIGN KEY (id_unidad) REFERENCES Unidades(id_unidad),
    FOREIGN KEY (id_vendedor) REFERENCES Vendedores(id_vendedor),

    CHECK (turno IN ('Mañana', 'Tarde')),
    CHECK (clientes_visitados >= 0),
    CHECK (ventas >= 0),
    CHECK (monto_regreso >= 0),
    CHECK (monto_regreso <= ventas),
    CHECK (mapeo IN ('Disponible', 'No disponible'))
)
GO


