SELECT * FROM Recorridos

-- TABLA VENTAS 
CREATE TABLE Ventas (
    id_venta VARCHAR(10) PRIMARY KEY,
    fecha DATE NOT NULL,
    id_cliente VARCHAR(10) NOT NULL,
    id_vendedor VARCHAR(10) NOT NULL,
    id_unidad VARCHAR(10) NOT NULL,
    id_zona VARCHAR(10) NOT NULL,
    id_recorrido VARCHAR(10) NOT NULL,
    documento VARCHAR(20) NOT NULL,
    tipo_precio VARCHAR(10) NOT NULL,
    total DECIMAL(10,2) NOT NULL,

    FOREIGN KEY (id_cliente) REFERENCES Clientes(id_cliente),
    FOREIGN KEY (id_vendedor) REFERENCES Vendedores(id_vendedor),
    FOREIGN KEY (id_unidad) REFERENCES Unidades(id_unidad),
    FOREIGN KEY (id_zona) REFERENCES Zonas(id_zona),
    FOREIGN KEY (id_recorrido) REFERENCES Recorridos(id_recorrido),

    CHECK (tipo_precio IN ('Unitario', 'Mayor')),
    CHECK (total >= 0)
)
GO

